return '<tr><td>' + (numbered ? item.number + 'ª' : esc(item.description)) + '</td><td>' + day(item.due_on) + '</td><td class="is-num">' + brl(item.amount_cents) + '</td><td>' + esc(state) + '</td></tr>';
