var fees = parseCents($('[name="fees_cents"]', form).value);
var discount = parseCents($('[name="discount_cents"]', form).value);
var n = parseInt($('[name="installments"]', form).value || '0', 10);
if (isNaN(fees) || isNaN(discount)) { summary.textContent = 'Confira os valores de encargos e desconto.'; return; }
var total = debt + fees - discount;
var each = n > 0 ? Math.floor(total / n) : 0;
summary.innerHTML = '<div>Dívida <strong>' + brl(debt) + '</strong> + encargos ' + brl(fees) + ' − desconto ' + brl(discount) + ' = <strong>' + brl(total) + '</strong>' +
(n > 0 && total > 0 ? ' em ' + n + 'x de ' + brl(each) + (total - each * n ? ' (a 1ª com ' + brl(each + total - each * n) + ')' : '') : '') + '</div>';
